// See code-nodes/parse-pitchbook.js for annotated version

function getISOWeekLabel(date) {
  const d = new Date(date);
  d.setHours(0, 0, 0, 0);
  d.setDate(d.getDate() + 4 - (d.getDay() || 7));
  const yearStart = new Date(d.getFullYear(), 0, 1);
  const weekNo = Math.ceil((((d - yearStart) / 86400000) + 1) / 7);
  return `W${d.getFullYear()}-${String(weekNo).padStart(2, '0')}`;
}

function cleanWebsite(raw) {
  if (!raw) return '';
  const s = String(raw).trim();
  if (s.toLowerCase().includes('pitchbook.com')) return '';
  return s;
}

return items.map(item => {
  const pb  = item.json.pitchbook_raw_text || {};
  const text = (pb.text || '').toString();
  const pitchbookUrl = (pb.url || '').trim();

  const companyName = text.split('\n').map(l => l.trim()).find(l => l.length > 0) || '';

  const websiteMatch = text.match(/Website\s+([^\n]+)/i);
  const websiteUrl   = cleanWebsite(websiteMatch ? websiteMatch[1].trim() : '');

  const descMatch = text.match(
    /Description\s+([\s\S]*?)(?:\nMost Recent Financing Status|\nWebsite|\nEmployees|\nPrimary Contact)/i
  );
  const about = descMatch ? descMatch[1].replace(/\s+/g, ' ').trim() : '';

  const primaryContactMatch = text.match(/Primary Contact\s+([^\n]+)/i);
  const primaryContact = primaryContactMatch ? primaryContactMatch[1].trim() : '';
  const firstName = primaryContact ? primaryContact.split(/\s+/)[0] : '';

  const emailMatch = text.match(/[A-Z0-9._%+\-]+@[A-Z0-9.\-]+\.[A-Z]{2,}/i);
  const email = emailMatch ? emailMatch[0].toLowerCase() : '';

  const today    = new Date();
  const dateAdded = today.toISOString().split('T')[0];
  const batchId   = getISOWeekLabel(today);

  return {
    json: {
      pitchbook_url: pitchbookUrl,
      company_name:  companyName,
      website_url:   websiteUrl,
      first_name:    firstName,
      email:         email,
      linkedin_url:  '',
      about:         about,
      date_added:    dateAdded,
      batch_id:      batchId,
      channel:       '',
      contacted_at:  '',
    },
  };
});

// See code-nodes/prep-linkedin-lookup.js for annotated version

function normalizeDomain(input) {
  if (!input) return '';
  let s = String(input).trim();
  if (s.toLowerCase().includes('pitchbook.com')) return '';
  if (!/^https?:\/\//i.test(s)) s = 'https://' + s;
  try {
    const u = new URL(s);
    return (u.hostname || '').toLowerCase().replace(/^www\./, '');
  } catch {
    return s.toLowerCase().replace(/^https?:\/\//, '').replace(/^www\./, '').split('/')[0];
  }
}

function isValidLinkedInProfile(s) {
  if (!s) return false;
  const v = String(s).toLowerCase().trim();
  return v.includes('linkedin.com/in/') || v.includes('linkedin.com/pub/');
}

function generateSessionId() {
  return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, c => {
    const r = (Math.random() * 16) | 0;
    return (c === 'x' ? r : (r & 0x3) | 0x8).toString(16);
  });
}

return items
  .map(item => {
    const row = item.json;
    if (isValidLinkedInProfile(row.linkedin_url || row['Founder Linkedin'])) return null;

    const company   = (row.company_name  || row['Company Name']  || '').trim();
    const firstName = (row.first_name    || row['First Name']    || '').trim();
    const email     = (row.email         || row['Email']         || '').trim();

    const websiteDomain = normalizeDomain(row.website_url || row['Url']);
    const emailDomain   = email.includes('@') ? normalizeDomain(email.split('@')[1]) : '';
    const domain        = websiteDomain || emailDomain;

    const queries = [];
    if (firstName && company) queries.push(`"${firstName}" "${company}" site:linkedin.com/in`);
    if (firstName && domain)  queries.push(`"${firstName}" "${domain}" site:linkedin.com/in`);
    if (company)              queries.push(`"${company}" founder OR CEO site:linkedin.com/in`);

    const primaryQuery = queries[0] || `${company} founder LinkedIn`;

    return {
      json: {
        ...row,
        normalized_company: company,
        normalized_domain:  domain,
        domain,
        needs_lookup:       true,
        primary_query:      primaryQuery,
        queries,
        sessionId:          generateSessionId(),
      },
    };
  })
  .filter(Boolean);

// See code-nodes/sanitize-query.js for annotated version

function isBlockedPattern(q) {
  if (!q) return true;
  const s = q.toLowerCase();
  return s.includes('site:linkedin.com/in') && /\b(founder|cofounder|ceo)\b/.test(s);
}

return items.map(item => {
  const row     = item.json;
  const company = row.normalized_company || row.company_name || '';
  const domain  = row.domain || '';
  let query     = row.primary_query || '';

  if (isBlockedPattern(query)) {
    if (company && domain)  query = `"${company}" "${domain}" linkedin founder`;
    else if (company)       query = `"${company}" linkedin founder`;
    else if (domain)        query = `"${domain}" linkedin founder`;
    else                    query = 'linkedin founder';
  }

  return { json: { ...row, primary_query: query } };
});

// A Merge node upstream combines:
//   input 0 — Serper HTTP response
//   input 1 — lead fields from Sanitize Query (passed on parallel branch)
// So items[0].json contains ALL fields from both sources.

const data = items[0].json;

const firstName   = (data.first_name   || data['First Name']   || '').toLowerCase().trim();
const companyName = (data.company_name || data['Company Name'] || '').toLowerCase().trim();
const domainRaw   = (data.domain       || data.normalized_domain || '').toLowerCase().trim();
const domainToken = domainRaw.split('.')[0];

const organic    = data.organic   || [];
const knowledge  = data.knowledgeGraph ? [data.knowledgeGraph] : [];
const allResults = [...organic, ...knowledge];

const candidates = [];
for (const r of allResults) {
  const url     = (r.link || r.website || '').trim();
  const title   = (r.title   || r.description || '').toLowerCase();
  const snippet = (r.snippet || '').toLowerCase();
  if (url.toLowerCase().includes('linkedin.com/in/')) {
    candidates.push({ url, text: `${title} ${snippet}` });
  }
}

function score(c) {
  const t = c.text;
  let s = 0;
  if (firstName   && t.includes(firstName))   s += 4;
  if (companyName && t.includes(companyName)) s += 3;
  if (domainToken && t.includes(domainToken)) s += 2;
  if (t.includes('reid hoffman'))                          s -= 20;
  if (c.url.toLowerCase().includes('reidhoffman'))         s -= 20;
  if (t.includes('co-founder of linkedin'))               s -= 20;
  if (c.url.toLowerCase().includes('/in/linkedin'))        s -= 10;
  return s;
}

candidates.sort((a, b) => score(b) - score(a));
const best      = candidates[0];
const bestScore = best ? score(best) : -99;
const linkedInUrl = (best && bestScore > 0) ? best.url : '';

return [{
  json: {
    pitchbook_url:            data.pitchbook_url || '',
    email:                    data.email         || '',
    linkedin_url:             linkedInUrl,
    _debug_query_used:        data.primary_query || '',
    _debug_first_name:        firstName,
    _debug_company_name:      companyName,
    _debug_candidates_found:  candidates.length,
    _debug_best_score:        bestScore,
  },
}];

// See code-nodes/channel-router.js for annotated version

function isValidLinkedInProfile(s) {
  if (!s) return false;
  const v = String(s).toLowerCase().trim();
  return v.includes('linkedin.com/in/') || v.includes('linkedin.com/pub/');
}

function getChannel(record) {
  const hasEmail    = !!(record.email || '').trim();
  const hasLinkedIn = isValidLinkedInProfile(record.linkedin_url);
  if (hasEmail && hasLinkedIn)  return 'email_linkedin';
  if (hasLinkedIn && !hasEmail) return 'linkedin_only';
  if (hasEmail && !hasLinkedIn) return 'email_only';
  return 'none';
}

return items.map(item => ({
  json: { ...item.json, channel: getChannel(item.json) }
}));
